package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
)

func handler(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/health" {
		http.NotFound(w, r)
		return
	}
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		http.Error(w, "method", http.StatusMethodNotAllowed)
		return
	}
	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte("ready"))
}
func main() {
	for _, item := range []struct{ method, path string }{{"GET", "/health"}, {"POST", "/health"}, {"GET", "/missing"}} {
		r := httptest.NewRequest(item.method, item.path, nil)
		w := httptest.NewRecorder()
		handler(w, r)
		fmt.Printf("%s %s=%d allow=%q\n", item.method, item.path, w.Code, w.Header().Get("Allow"))
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"mime"
	"net/http"
	"net/http/httptest"
	"strings"
)

type Input struct {
	Name string `json:"name"`
}

func post(w http.ResponseWriter, r *http.Request) {
	media, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || media != "application/json" {
		http.Error(w, "media", 415)
		return
	}
	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 128))
	decoder.DisallowUnknownFields()
	var input Input
	if err = decoder.Decode(&input); err != nil {
		http.Error(w, "json", 400)
		return
	}
	var tail interface{}
	if decoder.Decode(&tail) != io.EOF || input.Name == "" {
		http.Error(w, "payload", 400)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(input)
}
func main() {
	for _, item := range []struct{ media, body string }{{"application/json", `{"name":"Li"}`}, {"application/json", `{"name":"Li","admin":true}`}, {"application/json", `{"name":"Li"}{}`}, {"text/plain", `{"name":"Li"}`}} {
		r := httptest.NewRequest("POST", "/profile", strings.NewReader(item.body))
		r.Header.Set("Content-Type", item.media)
		w := httptest.NewRecorder()
		post(w, r)
		fmt.Println(w.Code)
	}
}

package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
)

type requestKey struct{}

func identify(next http.Handler) http.Handler {
	counter := 0
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := r.Header.Get("X-Request-ID")
		if id == "" {
			counter++
			id = fmt.Sprintf("local-%d", counter)
		}
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), requestKey{}, id)))
	})
}
func main() {
	app := identify(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id, ok := r.Context().Value(requestKey{}).(string)
		if !ok {
			panic("missing ID")
		}
		fmt.Fprint(w, id)
	}))
	for _, id := range []string{"provided-7", ""} {
		r := httptest.NewRequest("GET", "/", nil)
		if id != "" {
			r.Header.Set("X-Request-ID", id)
		}
		w := httptest.NewRecorder()
		app.ServeHTTP(w, r)
		fmt.Printf("header=%s body=%s\n", w.Header().Get("X-Request-ID"), w.Body.String())
	}
}

package main

import (
	"crypto/sha256"
	"fmt"
	"net/http"
	"net/http/httptest"
)

func main() {
	body := []byte("offline catalog")
	sum := sha256.Sum256(body)
	etag := fmt.Sprintf("\"%x\"", sum[:8])
	app := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("ETag", etag)
		if r.Header.Get("If-None-Match") == etag {
			w.WriteHeader(http.StatusNotModified)
			return
		}
		w.Write(body)
	})
	for _, match := range []bool{false, true} {
		r := httptest.NewRequest("GET", "/catalog", nil)
		if match {
			r.Header.Set("If-None-Match", etag)
		}
		w := httptest.NewRecorder()
		app.ServeHTTP(w, r)
		fmt.Printf("match=%t status=%d bytes=%d\n", match, w.Code, w.Body.Len())
	}
}

package main

import (
	"fmt"
	"mime"
	"strconv"
	"strings"
)

func choose(accept string) string {
	best := ""
	quality := 0.0
	for _, part := range strings.Split(accept, ",") {
		media, params, err := mime.ParseMediaType(strings.TrimSpace(part))
		if err != nil {
			continue
		}
		q := 1.0
		if value, ok := params["q"]; ok {
			q, err = strconv.ParseFloat(value, 64)
			if err != nil || q < 0 || q > 1 {
				continue
			}
		}
		if media != "text/plain" && media != "application/json" {
			continue
		}
		if q > quality {
			best = media
			quality = q
		}
	}
	return best
}
func main() {
	for _, input := range []string{"application/json;q=0.4, text/plain;q=0.9", "text/plain;q=0, application/json;q=0", "text/plain;q=bad, application/json"} {
		fmt.Printf("selected=%q\n", choose(input))
	}
}

package main

import (
	"fmt"
	"net/url"
	"sort"
)

func main() {
	input, err := url.ParseQuery("tag=offline&secret=x&page=2&tag=go")
	if err != nil {
		panic(err)
	}
	allowed := map[string]bool{"tag": true, "page": true}
	clean := url.Values{}
	dropped := 0
	for key, values := range input {
		if !allowed[key] {
			dropped++
			continue
		}
		copyValues := append([]string(nil), values...)
		sort.Strings(copyValues)
		clean[key] = copyValues
	}
	fmt.Printf("query=%s\ndropped-keys=%d\ntag-count=%d\n", clean.Encode(), dropped, len(clean["tag"]))
	_, err = url.ParseQuery("name=%ZZ")
	fmt.Printf("invalid-escape=%t\n", err != nil)
}

package main

import (
	"fmt"
	"net/url"
)

func main() {
	base, err := url.Parse("https://example.test/docs/guide/index.html?lang=en")
	if err != nil {
		panic(err)
	}
	for _, text := range []string{"../api.html", "?lang=zh", "#usage", "/assets/a.png"} {
		ref, err := url.Parse(text)
		if err != nil {
			panic(err)
		}
		resolved := base.ResolveReference(ref)
		fmt.Printf("%s -> %s\n", text, resolved.String())
	}
	fmt.Printf("base-unchanged=%t\n", base.RawQuery == "lang=en")
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"net/http"
	"strings"
)

func main() {
	wire := "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\nTrailer: X-Total\r\n\r\n3\r\ngo!\r\n2\r\nok\r\n0\r\nX-Total: 5\r\n\r\n"
	r, err := http.ReadResponse(bufio.NewReader(strings.NewReader(wire)), nil)
	if err != nil {
		panic(err)
	}
	before := r.Trailer.Get("X-Total")
	body, err := io.ReadAll(r.Body)
	r.Body.Close()
	if err != nil {
		panic(err)
	}
	fmt.Printf("status=%d\nbody=%s\ntrailer-before=%q\ntrailer-after=%s\n", r.StatusCode, body, before, r.Trailer.Get("X-Total"))
}
